using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
namespace FlowDesk {
[ComImport,Guid("A5CD92FF-29BE-454C-8D04-D82879FB3F1B"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IDesktopManager {
 [PreserveSig]int IsWindowOnCurrentVirtualDesktop(IntPtr window,[MarshalAs(UnmanagedType.Bool)]out bool current);
 [PreserveSig]int GetWindowDesktopId(IntPtr window,out Guid id);
 [PreserveSig]int MoveWindowToDesktop(IntPtr window,ref Guid id);
}
public static class DesktopAccess {
 public static bool BringCandidate(Candidate candidate,IntPtr host,out string reason){reason="";if(!Native.IsWindow(candidate.H)){reason="Selected window was closed.";return false;}int pid=(int)Native.Pid(candidate.H);long started=Process.GetProcessById(pid).StartTime.ToUniversalTime().Ticks;if((candidate.ProcessId!=0&&candidate.ProcessId!=pid)||(candidate.Started!=0&&candidate.Started!=started)){reason="Selected window identity changed. Refresh and select it again.";return false;}candidate.ProcessId=pid;candidate.Started=started;if(!Native.Cloaked(candidate.H))return true;if(BringHere(candidate.H,host,out reason)){var watch=Stopwatch.StartNew();while(Native.Cloaked(candidate.H)&&watch.ElapsedMilliseconds<800)Thread.Sleep(20);if(!Native.Cloaked(candidate.H))return true;}int original;string originalId;if(!DesktopBridge.MoveHere(candidate.H,host,out original,out originalId,out reason))return false;candidate.OriginalDesktop=original;candidate.OriginalDesktopId=originalId;var clock=Stopwatch.StartNew();while(Native.Cloaked(candidate.H)&&clock.ElapsedMilliseconds<1200)Thread.Sleep(20);if(!Native.Cloaked(candidate.H)){candidate.OtherDesktop=false;return true;}DesktopBridge.RestoreCandidate(candidate);candidate.OriginalDesktop=-1;reason="Window did not become available after the desktop move.";return false;}
 static IDesktopManager Create(){return (IDesktopManager)Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("AA509086-5CA9-4C25-8F95-589D3C07B48A")));}
 public static bool IsOther(IntPtr window){IDesktopManager manager=null;try{manager=Create();bool current;return manager.IsWindowOnCurrentVirtualDesktop(window,out current)==0&&!current;}catch{return Native.Cloaked(window);}finally{if(manager!=null)Marshal.ReleaseComObject(manager);}}
 public static bool BringHere(IntPtr window,IntPtr host,out string reason){IDesktopManager manager=null;try{manager=Create();Guid id;int result=manager.GetWindowDesktopId(host,out id);if(result==0)result=manager.MoveWindowToDesktop(window,ref id);if(result==0){reason="";return true;}reason="Windows did not allow moving this application (0x"+result.ToString("X8")+"). Move it here in Task View, then Refresh and select it again.";return false;}catch(Exception e){reason="Cannot move this application automatically. Move it here in Task View, then Refresh. "+e.Message;return false;}finally{if(manager!=null)Marshal.ReleaseComObject(manager);}}
}
public class WindowSelection {
 public List<Candidate> Allowed=new List<Candidate>(),Skipped=new List<Candidate>();
 public static WindowSelection Build(IEnumerable<Candidate> candidates,Func<Candidate,bool> canLink){var result=new WindowSelection();foreach(var candidate in candidates){if(canLink(candidate))result.Allowed.Add(candidate);else result.Skipped.Add(candidate);}return result;}
}
public class InstalledApp {
 public string Name,Target,ExpectedPath;public bool Packaged;
 public static InstalledApp FromFile(string file){string extension=Path.GetExtension(file);if(!extension.Equals(".exe",StringComparison.OrdinalIgnoreCase)&&!extension.Equals(".lnk",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Choose an .exe or .lnk shortcut.");if(!File.Exists(file))throw new FileNotFoundException("Application or shortcut no longer exists.",file);var app=new InstalledApp{Name=Path.GetFileNameWithoutExtension(file),Target=Path.GetFullPath(file),ExpectedPath=extension.Equals(".exe",StringComparison.OrdinalIgnoreCase)?Path.GetFullPath(file):null};if(app.ExpectedPath==null){object shell=null,link=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic automation=shell;link=automation.CreateShortcut(app.Target);dynamic shortcut=link;string target=Environment.ExpandEnvironmentVariables((string)shortcut.TargetPath);if(File.Exists(target)&&Path.GetExtension(target).Equals(".exe",StringComparison.OrdinalIgnoreCase))app.ExpectedPath=Path.GetFullPath(target);}catch{}finally{if(link!=null)Marshal.ReleaseComObject(link);if(shell!=null)Marshal.ReleaseComObject(shell);}}return app;}
 public Process Launch(){if(Packaged)return Process.Start(new ProcessStartInfo("explorer.exe","shell:AppsFolder\\"+Target){UseShellExecute=true});if(!File.Exists(Target))throw new FileNotFoundException("Application or shortcut no longer exists.",Target);return Process.Start(new ProcessStartInfo(Target){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(Target)});}
}
public static class AppCatalog {
 public static List<InstalledApp> Read(){var apps=new List<InstalledApp>();foreach(string root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.Programs),Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms)}){var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){string folder=pending.Pop();try{foreach(string sub in Directory.GetDirectories(folder))if((File.GetAttributes(sub)&FileAttributes.ReparsePoint)==0)pending.Push(sub);foreach(string file in Directory.GetFiles(folder,"*.lnk")){if(Path.GetFileName(file).IndexOf("uninstall",StringComparison.OrdinalIgnoreCase)>=0)continue;try{apps.Add(InstalledApp.FromFile(file));}catch{}}}catch{}}}
  object shell=null,folderObject=null,itemsObject=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("Shell.Application"));dynamic automation=shell;folderObject=automation.NameSpace("shell:AppsFolder");dynamic folder=folderObject;itemsObject=folder.Items();dynamic items=itemsObject;foreach(object itemObject in items){try{dynamic item=itemObject;string id=item.Path;string name=item.Name;if(!string.IsNullOrWhiteSpace(id)&&id.Contains("!"))apps.Add(new InstalledApp{Name=name,Target=id,Packaged=true});}finally{Marshal.ReleaseComObject(itemObject);}}}catch{}finally{if(itemsObject!=null)Marshal.ReleaseComObject(itemsObject);if(folderObject!=null)Marshal.ReleaseComObject(folderObject);if(shell!=null)Marshal.ReleaseComObject(shell);}
  return apps.GroupBy(a=>a.Name+"|"+a.Target,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).OrderBy(a=>a.Name,StringComparer.CurrentCultureIgnoreCase).ToList();
 }
 public static Candidate UniqueNewWindow(IEnumerable<Candidate> windows,HashSet<IntPtr> before,string path,int process){var matches=windows.Where(c=>!before.Contains(c.H)&&!c.OtherDesktop&&((!string.IsNullOrEmpty(path)&&string.Equals(c.Path,path,StringComparison.OrdinalIgnoreCase))||(process!=0&&c.ProcessId==process))).ToArray();return matches.Length==1?matches[0]:null;}
}
public class RunAppDialog:Form {
 ListView list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=false};TextBox search=new TextBox{Dock=DockStyle.Top};Label status=new Label{Dock=DockStyle.Bottom,Height=42,Text="Loading installed apps…",Padding=new Padding(8)};Button run,browse;List<InstalledApp> apps=new List<InstalledApp>();System.Windows.Forms.Timer poll=new System.Windows.Forms.Timer{Interval=500};HashSet<IntPtr> before;Process launched;InstalledApp launching;DateTime deadline;IntPtr stable;int stableTicks;ImageList icons=new ImageList{ImageSize=new Size(16,16),ColorDepth=ColorDepth.Depth32Bit};
 public Candidate Selected;public string Mode="Aligned";
 public RunAppDialog(){Text="Run app";Size=new Size(720,520);Theme.Style(this);list.BackColor=Theme.Bg;list.ForeColor=Theme.Ink;list.Columns.Add("Application",350);list.Columns.Add("Source",240);list.SmallImageList=icons;Controls.Add(list);Controls.Add(search);Controls.Add(status);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=40};run=Theme.Button("Run selected",delegate{if(list.SelectedItems.Count==1)Launch((InstalledApp)list.SelectedItems[0].Tag);});browse=Theme.Button("Browse .exe / shortcut…",delegate{using(var dialog=new OpenFileDialog{Filter="Applications and shortcuts|*.exe;*.lnk",CheckFileExists=true})if(dialog.ShowDialog(this)==DialogResult.OK){try{Launch(InstalledApp.FromFile(dialog.FileName));}catch(Exception e){status.Text=e.Message;}}});bar.Controls.Add(run);bar.Controls.Add(browse);bar.Controls.Add(Theme.Button("Choose running window…",delegate{poll.Stop();using(var picker=new Picker()){if(picker.ShowDialog(this)==DialogResult.OK&&picker.Selected.Count>0){Selected=picker.Selected[0];Mode=picker.Mode;DialogResult=DialogResult.OK;}}}));Controls.Add(bar);search.TextChanged+=delegate{Render();};list.DoubleClick+=delegate{run.PerformClick();};poll.Tick+=delegate{Detect();};
  Shown+=delegate{var worker=new Thread(delegate(){var result=AppCatalog.Read();try{if(!IsDisposed)BeginInvoke((Action)delegate{if(IsDisposed)return;apps=result;Render();if(launching==null)status.Text=apps.Count+" installed apps. Search or browse an executable/shortcut.";});}catch(InvalidOperationException){}});worker.IsBackground=true;worker.SetApartmentState(ApartmentState.STA);worker.Start();};
 }
 void Render(){list.BeginUpdate();list.Items.Clear();icons.Images.Clear();foreach(var app in apps.Where(a=>a.Name.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0)){int image=-1;try{string path=app.ExpectedPath??(app.Packaged?null:app.Target);if(path!=null){using(var icon=Icon.ExtractAssociatedIcon(path))if(icon!=null){icons.Images.Add(icon);image=icons.Images.Count-1;}}}catch{}list.Items.Add(new ListViewItem(new[]{app.Name,app.Packaged?"Windows app":"Start menu shortcut"},image){Tag=app});}list.EndUpdate();}
 void Launch(InstalledApp app){if(poll.Enabled)return;try{before=new HashSet<IntPtr>(Candidate.All(true).Select(c=>c.H));launching=app;launched=app.Launch();deadline=DateTime.UtcNow.AddSeconds(15);stable=IntPtr.Zero;stableTicks=0;run.Enabled=browse.Enabled=false;list.Enabled=false;status.Text="Opening "+app.Name+"… Waiting for its window. Closing this dialog leaves the app running.";poll.Start();}catch(Exception e){launching=null;status.Text="Could not start application: "+e.Message;run.Enabled=browse.Enabled=list.Enabled=true;}}
 void Detect(){try{int process=0;if(!launching.Packaged&&launched!=null)try{if(!launched.HasExited)process=launched.Id;}catch{}var candidate=AppCatalog.UniqueNewWindow(Candidate.All(),before,launching.ExpectedPath,process);if(candidate!=null){if(candidate.H==stable)stableTicks++;else{stable=candidate.H;stableTicks=1;}if(stableTicks>=3){poll.Stop();Selected=candidate;DialogResult=DialogResult.OK;return;}}else{stable=IntPtr.Zero;stableTicks=0;}if(DateTime.UtcNow>=deadline){poll.Stop();run.Enabled=browse.Enabled=list.Enabled=true;status.Text="No unique new application window found. It may have reused an existing window. Use Choose running window to select it.";}}catch(Exception e){poll.Stop();run.Enabled=browse.Enabled=list.Enabled=true;status.Text=e.Message;}}
 protected override void Dispose(bool disposing){if(disposing){poll.Dispose();icons.Dispose();if(launched!=null)launched.Dispose();}base.Dispose(disposing);}
}
}
